"""Freeze two development-only diagnostic units, no model/scorer execution."""
import copy,difflib,json,hashlib,random,shutil
from pathlib import Path
OUT=Path(__file__).resolve().parent;ROOT=OUT.parents[1];OLD=OUT.parent/'gepa-official-skill-experiment-v1-20261106';PROJ=OUT.parent/'gepa-feedback-projection-v1-20261106'
def read(p):return json.loads(Path(p).read_text())
def sha(v):return hashlib.sha256(v if isinstance(v,bytes) else v.encode()).hexdigest()
def save(p,v):p=Path(p);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
def main():
 from gepa.strategies.instruction_proposal import InstructionProposalSignature
 rows={r['id']:r for r in read(OLD/'task-results.json')};units=[dict(id='U1',job='e-5b07bf1156dc48d0',reason='Only one required relation fails (9/10): extra new input from the retired source enters history after navigation during startup; current attempt replacement is already preserved.'),dict(id='U2',job='e-0f86af18a30343df',reason='Different task/effect relation: pending preparation has retry and later delivery but loses the waiting indication (7/8); access invalidation and other seven required behaviors pass.')];keys=[];info=[]
 for u in units:
  r=rows[u['job']];folder=OUT/'inputs'/u['id'];folder.mkdir(parents=True,exist_ok=True);p0=read(PROJ/'examples'/r['id']/'F0.feedback.json');p1=read(PROJ/'examples'/r['id']/'F1.feedback.json');assert p0['Inputs']==p1['Inputs']
  skill=next(read(f)['temporal_skill'] for f in (OLD/'candidates').glob('*/candidate.json') if sha(read(f)['temporal_skill'])==r['skill_sha256']);(folder/'parent.md').write_text(skill)
  common=copy.deepcopy(p0);common.pop('Feedback');save(folder/'common-record.json',common)
  prompts={};blocks={}
  template=(OUT/'REFLECTION_TEMPLATE.md').read_text();suffix=template.split('<side_info>')[1]
  for condition,feedback in [('A',p0['Feedback']),('B',p1['Feedback'])]:
   d=copy.deepcopy(common);d['Feedback']=feedback;save(folder/(condition+'.feedback.json'),feedback)
   text=InstructionProposalSignature.prompt_renderer(dict(current_instruction_doc=skill,dataset_with_feedback=[d],prompt_template=template));assert text.endswith(suffix)
   delimiter='\n## Feedback\n';assert text.count(delimiter)==1;before,rest=text.split(delimiter,1);prefix=before+delimiter;block=rest[:-len(suffix)];prompts[condition]=text;blocks[condition]=block;(folder/(condition+'.prompt.md')).write_text(text);(folder/(condition+'.feedback-block.md')).write_text(block)
   if condition=='A':(folder/'common-prefix.md').write_text(prefix);(folder/'common-suffix.md').write_text(suffix)
   else:assert prefix==(folder/'common-prefix.md').read_text()
   assert len(text)<=72000
   assert not any(k in text for k in read(PROJ/'private-score-identifiers.json'))
  (folder/'input.diff').write_text(''.join(difflib.unified_diff(prompts['A'].splitlines(True),prompts['B'].splitlines(True),fromfile='A',tofile='B')))
  ignored=copy.deepcopy(p1['Generated_Outputs']);original=p0['Generated_Outputs'];changed=[k for k in original if original[k]!=ignored[k]];assert changed==['visible_validation']
  save(folder/'control-check.json',dict(parent_sha256=sha(skill),common_record_sha256=sha((folder/'common-record.json').read_bytes()),same_prefix_and_suffix=True,only_feedback_block_replaced=True,excluded_nonfeedback_F1_changes=changed,original_validation_bodies_kept_identical=True,original_duplicate_validation_bodies_count=len(original['visible_validation']),conditions={a:dict(prompt_characters=len(t),prompt_bytes=len(t.encode()),prompt_sha256=sha(t),feedback_characters=len(blocks[a])) for a,t in prompts.items()},input_cap=72000,new_truncation=False))
  evidence=OUT/'evidence'/u['id'];evidence.mkdir(parents=True,exist_ok=True);job=Path(r['path'])/'jobs/j-001';shutil.copyfile(r['raw_oracle'],evidence/'raw-score.json');shutil.copyfile(job/'events.jsonl',evidence/'events.jsonl');shutil.copyfile(job/'patch.diff',evidence/'patch.diff');shutil.copytree(PROJ/'materials'/r['case']/'input',evidence/'candidate-start',dirs_exist_ok=True);shutil.copyfile(PROJ/'materials'/r['case']/'task.md',evidence/'task.md')
  raw=read(r['raw_oracle']);failing=[dict(schedule=s,index=i,assertion=a) for s,v in raw['schedules'].items() for i,a in enumerate(v.get('assertions',[])) if a.get('passed') is False]
  key=dict(unit=u['id'],job=r['id'],case=r['case'],parent_skill_sha256=r['skill_sha256'],parent_origin='original pool seed K0' if u['id']=='U1' else 'original proposal P2, used as this unit frozen reflection parent; not mislabelled as original pool parent',selection_reason=u['reason'],whole_verdict=raw['verdict'],required_passed=r['score']['required_passed'],required_total=r['score']['required_total'],raw_failed_assertions=failing,raw_score_source=r['raw_oracle'],raw_score_sha256=sha(Path(r['raw_oracle']).read_bytes()),original_trajectory=str(job/'events.jsonl'),patch_source=str(job/'patch.diff'),passed_behaviors=[k for k,v in r['score']['checks'].items() if v],projection_source=dict(F0=str(PROJ/'examples'/r['id']/'F0.feedback.json'),F1=str(PROJ/'examples'/r['id']/'F1.feedback.json')),novelty='historically exposed development diagnostic; no held-out or generalization claim')
  if u['id']=='U1':key.update(target_relation='New source input after an ownership/navigation transition was recorded for the previous operation. Distinguish its admission from delayed completion of input already accepted before the transition.',direction='extra recorded effect from fresh obsolete-source input',preserve='Already accepted work may still record after hiding/navigation as source/task permits; display eligibility is separate. Preserve the already passing retry/queue/telemetry behavior.',acceptable_equivalents=['input admission versus completion validity','old producer continues accepting fresh inputs across synchronous ownership handoff','boundary of subscription/reception lifetime versus lifetime of already accepted work'],neighbor_errors=['only fix initial cached reception','only stop stale UI output','only examine delayed decode completing after hide without exercising new old-source input','only order two decoded frames within one watcher'],hypotheses=['lifecycle/handle handoff window','effect eligibility not checked at the appropriate event boundary'],unknowns=['No call-return markers in the raw trace; exact candidate stack must be source-checked.','No unique reference implementation follows from this observation.'],minimum_targeted_action='Source-qualified check: induce ownership change during startup/callback, then exercise fresh input from previous source and inspect history as well as current display; separately preserve already accepted completions.')
  else:key.update(target_relation='An individual request can finish pending while the overall preparation remains ongoing with a retry scheduled; waiting presentation/state is a separate effect from eventual successful delivery.',direction='missing assessed waiting indication during pending interval, with eventual completion retained',preserve='Preserve late-result invalidation after close/reopen, cleanup and eventual current delivery, plus the adjacent background policy.',acceptable_equivalents=['request lifecycle versus operation/preparation lifecycle','waiting/working indication across the gap between retry attempts','queued work, current access state and completion need separately evidenced transitions'],neighbor_errors=['only add polling/retry scheduling','only guard stale results after close','equate a pending response with preparation completed','declare loading must always remain true without checking source meaning'],hypotheses=['request-completion state transition conflated with overall preparation state'],unknowns=['The short task does not explicitly specify the loading flag schema.','Adjacent background behavior is evidence to inspect, not a binding foreground specification.','No rendered React check was run; archived syntax checks do not verify waiting behavior.'],minimum_targeted_action='Inspect which state drives waiting presentation; observe a pending response and the retry interval before readiness, then readiness and close/reopen, asserting waiting, delivery and scheduled work separately under source-backed semantics.')
  keys.append(key);info.append(dict(unit=u['id'],job=r['id'],case=r['case'],parent_skill_sha256=r['skill_sha256'],selection_reason=u['reason'],record_control=str(folder/'control-check.json')))
 save(OUT/'evidence-key.json',dict(research_only=True,not_added_to_any_model_prompt=True,units=keys,rating_labels=['满足','部分满足','不满足','证据不足'],no_quality_total=True))
 rng=random.Random(2026110606);first={u['id']:rng.sample(['A','B'],2) for u in units};schedule=[]
 for rep in [1,2]:
  order=list(units);rng.shuffle(order)
  for u in order:
   for arm in first[u['id']] if rep==1 else first[u['id']][::-1]:schedule.append(dict(sequence=len(schedule)+1,unit=u['id'],condition=arm,replicate=rep,call_id='r'+str(len(schedule)+1).zfill(2),prompt=str(OUT/'inputs'/u['id']/(arm+'.prompt.md'))))
 save(OUT/'schedule.json',dict(seed=2026110606,order=schedule,scope='eight independent one-request reflection generations, no model sampling seed'))
 save(OUT/'units.freeze.json',info)
 print('INPUTS_FROZEN',[(i['unit'],read(i['record_control'])['conditions']) for i in info])
if __name__=='__main__':main()
